export const envelope = [48, 22, 16];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 4;

  // 1. Palette selection from theme
  const stonePrimary = api.theme.stone.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone.accent || "minecraft:cobblestone";
  const stoneSlab = api.theme.stone.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme.stone.wall || "minecraft:stone_brick_wall";

  const groundPlinth = api.theme.ground.plinth || "minecraft:andesite";
  const groundPavement = api.theme.ground.pavement || "minecraft:gravel";
  const groundRevetment = api.theme.ground.revetment || "minecraft:cobblestone";

  const woodPlanks = api.theme.wood.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_spruce_log";
  const woodFence = api.theme.wood.fence || "minecraft:spruce_fence";
  const woodSlab = api.theme.wood.slab || "minecraft:spruce_slab";
  const woodStairs = api.theme.wood.stairs || "minecraft:spruce_stairs";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:spruce_trapdoor";

  const roofSolid = api.theme.roof.solid || "minecraft:dark_oak_planks";
  const roofStairs = api.theme.roof.stairs || "minecraft:dark_oak_stairs";

  // Authentic sacred Himalayan colors & materials
  const FLAG_COLORS = [
    "minecraft:blue_wool",
    "minecraft:white_wool",
    "minecraft:red_wool",
    "minecraft:lime_wool",
    "minecraft:yellow_wool",
  ];

  const calcite = "minecraft:calcite";
  const smoothQuartz = "minecraft:smooth_quartz";
  const goldBlock = "minecraft:gold_block";
  const redTerracotta = "minecraft:red_terracotta";
  const yellowTerracotta = "minecraft:yellow_terracotta";
  const polishedDeepslate = "minecraft:polished_deepslate";
  const deepslateSlab = "minecraft:polished_deepslate_slab";

  // Safe voxel setter
  function setSafe(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Terrain height query
  function getGroundY(x, z) {
    const h = api.heightAt(x, z);
    return Math.max(0, Math.min(H - 2, seatY + Math.round(h)));
  }

  // Foundation column builder (conforms to ground)
  function buildFoundationColumn(x, z, topY, block, bottomLimit = 0) {
    const gY = getGroundY(x, z);
    const startY = Math.max(bottomLimit, Math.min(gY, seatY));
    const endY = Math.max(topY, gY);
    for (let y = startY; y <= endY; y++) {
      setSafe(x, y, z, block);
    }
  }

  // 6-Connected Bresenham 3D line
  function line6(x1, y1, z1, x2, y2, z2, block) {
    let cx = Math.round(x1), cy = Math.round(y1), cz = Math.round(z1);
    const tx = Math.round(x2), ty = Math.round(y2), tz = Math.round(z2);
    setSafe(cx, cy, cz, block);
    while (cx !== tx || cy !== ty || cz !== tz) {
      const dx = Math.abs(tx - cx);
      const dy = Math.abs(ty - cy);
      const dz = Math.abs(tz - cz);
      if (dx >= dy && dx >= dz) {
        cx += Math.sign(tx - cx);
      } else if (dy >= dz) {
        cy += Math.sign(ty - cy);
      } else {
        cz += Math.sign(tz - cz);
      }
      setSafe(cx, cy, cz, block);
    }
  }

  // Catenary curve with suspended prayer flags
  function drawCatenaryWithFlags(p1, p2, sag, cableBlock, flagStyle = "dense") {
    const steps = Math.max(32, Math.round(Math.hypot(p2[0] - p1[0], p2[2] - p1[2]) * 2));
    let lastPos = null;
    let flagIndex = Math.floor(api.random() * 5);

    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const cx = Math.round(p1[0] + t * (p2[0] - p1[0]));
      const cz = Math.round(p1[2] + t * (p2[2] - p1[2]));
      const linearY = p1[1] + t * (p2[1] - p1[1]);
      const cy = Math.round(linearY - 4 * sag * t * (1 - t));

      if (lastPos) {
        line6(lastPos[0], lastPos[1], lastPos[2], cx, cy, cz, cableBlock);
      } else {
        setSafe(cx, cy, cz, cableBlock);
      }
      lastPos = [cx, cy, cz];

      // Prayer flags hanging from cable
      if (flagStyle === "dense" && i > 1 && i < steps - 1) {
        const color = FLAG_COLORS[flagIndex % 5];
        setSafe(cx, cy - 1, cz, color);

        // Fluttering tails and windward displacement
        if ((i % 3 === 0 || i % 4 === 0) && cy - 2 >= 2) {
          setSafe(cx, cy - 2, cz, color);
        }
        if (i % 5 === 2 && cx + 1 < W) {
          setSafe(cx + 1, cy - 1, cz, color);
        }

        if (i % 2 === 0) flagIndex++;
      } else if (flagStyle === "sparse" && i % 2 === 0 && i > 2 && i < steps - 2) {
        const color = FLAG_COLORS[flagIndex % 5];
        setSafe(cx, cy - 1, cz, color);
        flagIndex++;
      }
    }
  }

  // ==========================================
  // 1. WEST CLIFF BASTION & CHORTEN (X: 0..10)
  // ==========================================
  for (let x = 0; x <= 10; x++) {
    for (let z = 1; z <= 14; z++) {
      const isRim = (x === 10 || z === 1 || z === 14);
      const stoneMat = isRim ? stoneAccent : ((x + z) % 3 === 0 ? groundPlinth : stonePrimary);
      buildFoundationColumn(x, z, seatY, stoneMat);
    }
  }

  // Paved courtyard terrace
  for (let x = 1; x <= 9; x++) {
    for (let z = 2; z <= 13; z++) {
      setSafe(x, seatY, z, (x + z) % 2 === 0 ? groundPavement : stonePrimary);
    }
  }

  // Tibetan Chorten (Stupa) on North spur (X: 2..6, Z: 2..6)
  for (let x = 2; x <= 6; x++) {
    for (let z = 2; z <= 6; z++) {
      setSafe(x, seatY + 1, z, polishedDeepslate);
      setSafe(x, seatY + 2, z, (x === 2 || x === 6 || z === 2 || z === 6) ? deepslateSlab : stonePrimary);
    }
  }
  // Inset stepped terraces
  for (let x = 3; x <= 5; x++) {
    for (let z = 3; z <= 5; z++) {
      setSafe(x, seatY + 3, z, smoothQuartz);
    }
  }
  // Bumpa (Dome)
  for (let x = 3; x <= 5; x++) {
    for (let z = 3; z <= 5; z++) {
      setSafe(x, seatY + 4, z, calcite);
      setSafe(x, seatY + 5, z, calcite);
    }
  }
  // Rounded corners of the dome
  setSafe(3, seatY + 5, 3, smoothQuartz);
  setSafe(5, seatY + 5, 3, smoothQuartz);
  setSafe(3, seatY + 5, 5, smoothQuartz);
  setSafe(5, seatY + 5, 5, smoothQuartz);
  // Gau relic niche with butter lamp
  setSafe(5, seatY + 4, 4, "minecraft:lantern[hanging=false]");

  // Harmika (Spire base box)
  for (let x = 3; x <= 5; x++) {
    for (let z = 3; z <= 5; z++) {
      setSafe(x, seatY + 6, z, redTerracotta);
    }
  }
  setSafe(4, seatY + 6, 4, goldBlock);

  // Spire Rings (13 Tiers of Enlightenment)
  setSafe(4, seatY + 7, 4, smoothQuartz);
  setSafe(4, seatY + 8, 4, goldBlock);
  setSafe(4, seatY + 9, 4, smoothQuartz);
  setSafe(4, seatY + 10, 4, goldBlock);
  // Parasol & Sun-Moon Finial
  setSafe(4, seatY + 11, 4, goldBlock);
  setSafe(4, seatY + 12, 4, woodFence);
  setSafe(4, seatY + 13, 4, "minecraft:yellow_carpet");

  // West Pilgrim Prayer Shrine (X: 2..6, Z: 8..13)
  for (let x = 2; x <= 6; x++) {
    for (let z = 8; z <= 13; z++) {
      for (let y = seatY + 1; y <= seatY + 5; y++) {
        const isWall = (x === 2 || x === 6 || z === 8 || z === 13);
        if (isWall) {
          const isCorner = (x === 2 || x === 6) && (z === 8 || z === 13);
          setSafe(x, y, z, isCorner ? woodLog : stonePrimary);
        }
      }
      // Flat Tibetan slate roof with timber cornice
      setSafe(x, seatY + 5, z, roofSolid);
      if (x === 2 || x === 6 || z === 8 || z === 13) {
        setSafe(x, seatY + 6, z, (x + z) % 2 === 0 ? "minecraft:red_wool" : "minecraft:yellow_wool");
      }
    }
  }
  // Open doorway facing courtyard
  setSafe(4, seatY + 1, 8, "minecraft:air");
  setSafe(4, seatY + 2, 8, "minecraft:air");
  setSafe(4, seatY + 3, 8, woodStairs);
  // Shrine prayer windows
  setSafe(2, seatY + 2, 10, woodFence);
  setSafe(2, seatY + 2, 11, woodFence);

  // West Anchor Posts, Masts & Cable Windlasses (X: 8..10, Z: 5..9)
  for (let z = 5; z <= 9; z++) {
    setSafe(10, seatY + 1, z, stoneWall);
  }
  // Heavy timber mooring posts
  setSafe(9, seatY + 1, 6, woodLog);
  setSafe(9, seatY + 2, 6, woodLog);
  setSafe(9, seatY + 1, 9, woodLog);
  setSafe(9, seatY + 2, 9, woodLog);

  // Great West Prayer Mast (Darchen) at (9, Y, 5)
  for (let y = seatY + 1; y <= 20; y++) {
    setSafe(9, y, 5, woodLog);
    // Vertical streamer flags
    if (y >= seatY + 3 && y <= 19) {
      setSafe(9, y, 4, FLAG_COLORS[(y) % 5]);
      setSafe(8, y, 5, FLAG_COLORS[(y + 1) % 5]);
    }
  }
  setSafe(9, 21, 5, goldBlock);
  setSafe(9, 21, 6, woodFence);

  // ==========================================
  // 2. EAST CLIFF BASTION & MANI RIDGE (X: 37..47)
  // ==========================================
  for (let x = 37; x <= 47; x++) {
    for (let z = 1; z <= 14; z++) {
      const isRim = (x === 37 || z === 1 || z === 14);
      const stoneMat = isRim ? stoneAccent : ((x + z) % 3 === 0 ? groundPlinth : stonePrimary);
      buildFoundationColumn(x, z, seatY, stoneMat);
    }
  }

  // Paved path terrace
  for (let x = 38; x <= 46; x++) {
    for (let z = 2; z <= 13; z++) {
      setSafe(x, seatY, z, (x + z) % 2 === 0 ? groundPavement : stonePrimary);
    }
  }

  // East Mani Stone Cairn (Lhatse) at X: 41..45, Z: 3..7
  for (let x = 41; x <= 45; x++) {
    for (let z = 3; z <= 7; z++) {
      setSafe(x, seatY + 1, z, polishedDeepslate);
      if (x >= 42 && x <= 44 && z >= 4 && z <= 6) {
        setSafe(x, seatY + 2, z, stoneAccent);
        setSafe(x, seatY + 3, z, deepslateSlab);
      }
    }
  }
  // Juniper smoke burner (Sangkhang)
  setSafe(43, seatY + 2, 5, "minecraft:campfire[lit=true]");
  setSafe(43, seatY + 3, 5, stoneWall);

  // 3 Sacred East Prayer Poles
  for (let y = seatY + 1; y <= 18; y++) {
    setSafe(42, y, 4, woodLog);
    if (y >= seatY + 3 && y <= 17) setSafe(42, y, 3, FLAG_COLORS[y % 5]);
  }
  for (let y = seatY + 1; y <= 17; y++) {
    setSafe(44, y, 6, woodLog);
    if (y >= seatY + 3 && y <= 16) setSafe(45, y, 6, FLAG_COLORS[(y + 2) % 5]);
  }

  // East Trailhead Gateway Arch (X: 39..42, Z: 7..10)
  for (let y = seatY + 1; y <= seatY + 4; y++) {
    setSafe(39, y, 7, woodLog);
    setSafe(39, y, 10, woodLog);
  }
  for (let z = 7; z <= 10; z++) {
    setSafe(39, seatY + 4, z, roofSolid);
    setSafe(39, seatY + 5, z, roofStairs);
  }

  // East Anchor Mooring Buttress (X: 37..39, Z: 5..9)
  for (let z = 5; z <= 9; z++) {
    setSafe(37, seatY + 1, z, stoneWall);
  }
  setSafe(38, seatY + 1, 6, woodLog);
  setSafe(38, seatY + 2, 6, woodLog);
  setSafe(38, seatY + 1, 9, woodLog);
  setSafe(38, seatY + 2, 9, woodLog);

  // Great East Prayer Mast at (38, Y, 11)
  for (let y = seatY + 1; y <= 20; y++) {
    setSafe(38, y, 11, woodLog);
    if (y >= seatY + 3 && y <= 19) {
      setSafe(38, y, 12, FLAG_COLORS[(y + 3) % 5]);
      setSafe(39, y, 11, FLAG_COLORS[(y + 1) % 5]);
    }
  }
  setSafe(38, 21, 11, goldBlock);

  // ==========================================
  // 3. SUSPENSION FOOTBRIDGE (X: 10..37, Z: 7..8)
  // ==========================================
  for (let x = 10; x <= 37; x++) {
    const t = (x - 10) / 27;
    // Walkway catenary curve
    const yDeck = Math.round(9 - 4 * 2.0 * t * (1 - t));

    // Walkway deck (2 blocks wide)
    setSafe(x, yDeck, 7, woodPlanks);
    setSafe(x, yDeck, 8, woodPlanks);

    // Cross-beam ties and under-deck timber supports every 3 blocks
    if (x % 3 === 1 || x === 10 || x === 37) {
      for (let z = 6; z <= 9; z++) {
        setSafe(x, yDeck - 1, z, woodLog);
      }
      // Heavy timber vertical suspension posts
      setSafe(x, yDeck + 1, 6, woodFence);
      setSafe(x, yDeck + 2, 6, woodFence);
      setSafe(x, yDeck + 1, 9, woodFence);
      setSafe(x, yDeck + 2, 9, woodFence);
    } else {
      // Normal handrail fences
      setSafe(x, yDeck + 1, 6, woodFence);
      setSafe(x, yDeck + 1, 9, woodFence);
    }

    // Direct bridge-rail prayer flags fluttering below handrails
    if (x % 2 === 0) {
      const col1 = FLAG_COLORS[(x) % 5];
      const col2 = FLAG_COLORS[(x + 2) % 5];
      setSafe(x, yDeck, 6, col1);
      setSafe(x, yDeck, 9, col2);
    }
  }

  // ==========================================
  // 4. SUSPENSION CABLES & PRAYER FLAG CANOPY
  // ==========================================
  const catenaryLines = [
    // [p1, p2, sag, cableBlock, flagStyle]
    { p1: [9, 18, 3], p2: [38, 17, 3], sag: 5.5, block: woodFence, style: "dense" },
    { p1: [9, 21, 5], p2: [38, 20, 7], sag: 7.0, block: "minecraft:oak_fence", style: "dense" },
    { p1: [9, 20, 8], p2: [38, 20, 11], sag: 6.5, block: "minecraft:oak_fence", style: "dense" },
    { p1: [9, 18, 12], p2: [38, 18, 13], sag: 5.5, block: woodFence, style: "dense" },
    // Diagonal criss-cross garland webs
    { p1: [10, 19, 4], p2: [37, 17, 11], sag: 6.0, block: "minecraft:dark_oak_fence", style: "dense" },
    { p1: [10, 17, 11], p2: [37, 19, 4], sag: 6.0, block: "minecraft:dark_oak_fence", style: "dense" },
    // Lower secondary suspension strands
    { p1: [11, 14, 5], p2: [36, 14, 5], sag: 3.5, block: "minecraft:spruce_fence", style: "sparse" },
    { p1: [11, 14, 10], p2: [36, 14, 10], sag: 3.5, block: "minecraft:spruce_fence", style: "sparse" },
  ];

  for (const line of catenaryLines) {
    drawCatenaryWithFlags(line.p1, line.p2, line.sag, line.block, line.style);
  }

  // Vertical hanger ties connecting upper cables to bridge handrails
  for (let x = 13; x <= 34; x += 3) {
    const t = (x - 10) / 27;
    const yDeck = Math.round(9 - 4 * 2.0 * t * (1 - t));
    const upperYNorth = Math.round(18 - 4 * 5.5 * t * (1 - t));
    const upperYSouth = Math.round(18 - 4 * 5.5 * t * (1 - t));

    line6(x, yDeck + 2, 6, x, upperYNorth, 6, "minecraft:spruce_fence");
    line6(x, yDeck + 2, 9, x, upperYSouth, 9, "minecraft:spruce_fence");
  }

  // ==========================================
  // 5. GORGE BOTTOM, SCREE & CENTRAL CAIRN
  // ==========================================
  // Natural rock buttresses descending into gorge at cliff bases
  for (let z = 1; z <= 14; z++) {
    // West cliff slope
    buildFoundationColumn(11, z, seatY - 1, stoneAccent);
    buildFoundationColumn(12, z, seatY - 2, groundRevetment);
    // East cliff slope
    buildFoundationColumn(36, z, seatY - 1, stoneAccent);
    buildFoundationColumn(35, z, seatY - 2, groundRevetment);
  }

  // Sacred Gorge-Floor Mani Cairn & Rising Prayer Mast (X: 23..25, Z: 4..6)
  const cairnGroundY = getGroundY(24, 5);
  for (let x = 23; x <= 25; x++) {
    for (let z = 4; z <= 6; z++) {
      buildFoundationColumn(x, z, cairnGroundY + 1, stoneAccent, cairnGroundY);
      setSafe(x, cairnGroundY + 2, z, deepslateSlab);
    }
  }

  // Center Gorge Darchen Mast reaching up into the lower cable canopy
  for (let y = cairnGroundY + 1; y <= 11; y++) {
    setSafe(24, y, 5, woodLog);
    if (y >= cairnGroundY + 2 && y <= 10) {
      setSafe(24, y, 4, FLAG_COLORS[(y) % 5]);
    }
  }

  // Return structure metadata
  return {
    name: "prayer_flag_gorge_span",
    seatY: seatY,
    anchors: {
      front: [24, seatY, 0],
      door: [4, seatY + 1, 8],
      trail_west: [1, seatY + 1, 8],
      trail_east: [46, seatY + 1, 8],
      chorten: [4, seatY + 7, 4],
    },
    interiors: [
      {
        min: [3, seatY + 1, 9],
        max: [5, seatY + 3, 12],
        kind: "shrine",
      },
    ],
  };
}

